#include <cassert>
#include <cmath>
#include <iostream>
#include <stdexcept>
#ifdef NDEBUG
#error "Tests require assertions enabled."
#endif
struct Pose { double x, y; bool airborne; };
class Jump {
    double h_, t_, speed_;
public:
    Jump(double height, double apexTime, double speed)
        : h_(height), t_(apexTime), speed_(speed) {
        // 학습 모델의 유효 범위를 명시해 비정상 값과 수치 폭주를 막는다.
        if (!std::isfinite(h_) || h_ < 0.01 || h_ > 100.0 ||
            !std::isfinite(t_) || t_ < 0.05 || t_ > 5.0 ||
            !std::isfinite(speed_) || speed_ < 0.0 || speed_ > 100.0)
            throw std::invalid_argument("invalid jump parameters");
    }
    double gravity() const { return 2.0*h_/(t_*t_); }
    double launchSpeed() const { return 2.0*h_/t_; }
    Pose at(double elapsed) const {
        if (!std::isfinite(elapsed) || elapsed < 0.0 || elapsed > 1000000.0)
            throw std::invalid_argument("invalid elapsed time");
        const double landing = 2.0*t_;
        // 이 예제는 착지 후 수평 이동도 끝나는 한 번의 점프만 표현한다.
        const double active = elapsed < landing ? elapsed : landing;
        double y = launchSpeed()*active - 0.5*gravity()*active*active;
        if (y < 0.0 || elapsed >= landing) y = 0.0;
        return Pose{speed_*active, y, elapsed > 0.0 && elapsed < landing};
    }
};
bool near(double a, double b) { return std::fabs(a-b) < 1e-8; }
int main() {
    const Jump fast(2.0, 0.4, 4.0), slow(2.0, 0.6, 4.0);
    assert(near(fast.gravity(),25.0)); assert(near(fast.launchSpeed(),10.0));
    assert(near(fast.at(0.4).y,2.0)); assert(near(fast.at(0.8).x,3.2));
    assert(!fast.at(0.0).airborne && !fast.at(0.8).airborne);
    assert(fast.at(0.2).airborne); assert(near(fast.at(0.2).y,fast.at(0.6).y));
    assert(near(slow.at(0.6).y,2.0)); assert(near(slow.at(1.2).x,4.8));
    assert(near(fast.at(1000000.0).y,0.0));
    // 그리기 빈도가 아니라 경과 시간으로 계산하므로 같은 시각의 위치는 같다.
    // 아래 반복은 시간 샘플의 범위를 검사한다. 실제 엔진 충돌 검사는 아니다.
    for (int i=0;i<=10000;++i) {
        const Pose q=fast.at(i/10000.0);
        assert(q.y>=0.0 && q.y<=2.0+1e-8); assert(q.x>=0.0 && q.x<=3.2+1e-8);
    }
    int rejected=0;
    try { Jump bad(-1.0,0.4,4.0); } catch(const std::invalid_argument&) { ++rejected; }
    try { Jump bad(2.0,0.0,4.0); } catch(const std::invalid_argument&) { ++rejected; }
    try { fast.at(-0.01); } catch(const std::invalid_argument&) { ++rejected; }
    try { fast.at(std::nan("")); } catch(const std::invalid_argument&) { ++rejected; }
    assert(rejected==4);
    std::cout << "jump tests passed; fast range=3.2, slow range=4.8\n";
}
